import { ShoppingCart } from "lucide-react";

export default function ProductCard({
  product,
  isResident,
  isAdmin,
  orderQty,
  setQty,
  onBuy,
  onApprove,
  loading
}) {
  return (
    <div className="bg-white border rounded-xl p-4 shadow-sm hover:shadow-md transition">

      {/* Image Placeholder */}
      <div className="h-32 bg-gray-100 rounded-lg mb-3 flex items-center justify-center text-gray-400">
        Product Image
      </div>

      <div className="flex justify-between items-start">
        <h4 className="font-semibold">{product.name}</h4>

        <span className={`text-xs px-2 py-1 rounded-full
          ${product.is_approved
            ? "bg-green-100 text-green-700"
            : "bg-yellow-100 text-yellow-700"}
        `}>
          {product.is_approved ? "LIVE" : "PENDING"}
        </span>
      </div>

      <p className="text-sm text-gray-500 mt-1">
        {product.description}
      </p>

      <div className="text-sm mt-2">
        ₹{product.price} • Stock {product.quantity}
      </div>

      {/* Admin Approve */}
      {isAdmin && !product.is_approved && (
        <button
          onClick={() => onApprove(product.id)}
          className="mt-3 w-full bg-green-600 text-white rounded-lg py-2"
        >
          Approve Product
        </button>
      )}

      {/* Resident Buy */}
      {isResident && product.is_approved && (
        <div className="flex gap-2 mt-3">

          <input
            type="number"
            min="1"
            value={orderQty}
            onChange={(e) => setQty(product.id, e.target.value)}
            className="w-16 border rounded-lg px-2"
          />

          <button
            onClick={() => onBuy(product.id)}
            className="flex-1 bg-indigo-600 text-white rounded-lg py-2 flex items-center justify-center gap-2"
          >
            <ShoppingCart size={16} />
            {loading ? "..." : "Buy"}
          </button>

        </div>
      )}
    </div>
  );
}
